-- ชุดทุนประกัน/ความคุ้มครอง (จาก legacy master.PackagePatternCover) — ใช้ร่วมกันได้หลาย package
-- ชื่อ column คงคำย่อเดิม (od/odf/opd/opdf/bie/bip/sc03) ไว้ตามตัวย่อประกันภัยจริง ไม่ได้แปลเป็นชื่อยาว
-- เพราะไม่มั่นใจความหมายธุรกิจแบบเป๊ะๆ ของทุกฟิลด์ — รอ confirm ทีหลังได้ถ้าต้องการเปลี่ยน
CREATE TABLE package_covers (
    id                            BIGINT          GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code                          VARCHAR(10)   NOT NULL,
    cover_od                      NUMERIC(14,2) NOT NULL,
    cover_odf                     NUMERIC(14,2) NOT NULL,
    cover_opd                     NUMERIC(14,2) NOT NULL,
    cover_opdf                    NUMERIC(14,2) NOT NULL,
    cover_bie                     NUMERIC(14,2) NOT NULL,
    cover_bip                     NUMERIC(14,2) NOT NULL,
    driver_amount                 NUMERIC(14,2) NOT NULL,
    driver_amount_np              NUMERIC(14,2) NOT NULL,
    passenger_count                INT           NOT NULL,
    passenger_amount                NUMERIC(14,2) NOT NULL,
    passenger_count_np                INT           NOT NULL,
    passenger_amount_np                 NUMERIC(14,2) NOT NULL,
    driver_passenger_group_count           INT           NOT NULL,
    cover_p_amount                            NUMERIC(14,2) NOT NULL,
    sc03_amount                                  NUMERIC(14,2) NOT NULL,
    active_flag                                    BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at                                       TIMESTAMPTZ   NOT NULL,
    created_by                                          VARCHAR(100)  NOT NULL,
    updated_at                                             TIMESTAMPTZ   NOT NULL,
    updated_by                                                VARCHAR(100)  NOT NULL,
    version                                                      BIGINT        NOT NULL DEFAULT 0,

    CONSTRAINT uq_package_covers_code UNIQUE (code)
);

COMMENT ON TABLE package_covers IS 'ชุดทุนประกัน/ความคุ้มครอง จาก legacy master.PackagePatternCover — code เดิมเป็น CHAR(10) เติม space ท้าย ทำให้ SP เดิมต้อง LTRIM/RTRIM ทุก join, ที่นี่ trim แล้วเก็บเป็น varchar ตั้งแต่ต้น';

-- seed จากข้อมูลจริง legacy master.PackagePatternCover (304 แถว)
